import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { ValidatedScoringGeneration, ScoringCaptureValidationError } from '../../services/scoringCaptureValidation.js';
import { getScoringCaptureConfig } from '../../config/scoringCapture.js';

// Golden packet generated by the existing Python packet_for_frame codec. No
// model inference/quality or live user/catalog provenance is claimed by it.
const golden = JSON.parse(readFileSync(new URL('../fixtures/scoring-capture-v1.json', import.meta.url), 'utf8'));
const selector = { userId: golden.context.user_id, generationId: golden.context.generation_id,
  feedVersion: BigInt(golden.context.feed_version) };
const policy = { policyId: 'disposable-fixture', policyVersion: '1', retentionDays: 30 };
const candidate = () => ({ packet: structuredClone(golden.packet), rawHeavyScore: 0.25, finalScore: 0.3,
  source: 'semantic', retrievalScores: { semantic: 0.4 } });
const validate = (context = structuredClone(golden.context), row = candidate()) =>
  ValidatedScoringGeneration.validate(context, [row], selector);
const rejects = (work: () => unknown) => assert.throws(work, error =>
  error instanceof ScoringCaptureValidationError && error.message === 'SCORING_CAPTURE_INVALID'
  && !JSON.stringify(error).includes('input_base64'));

test('Python codec packet preserves exact input bytes, large decimal version and private serialization', () => {
  const validated = validate();
  const payload = JSON.parse(validated.serializeForPersistence(policy));
  assert.equal(payload.context_json, JSON.stringify(golden.context, Object.keys(golden.context).sort()));
  assert.equal(JSON.parse(payload.context_json).feed_version, '9007199254740993');
  assert.equal(payload.items[0].input_base64, golden.packet.input_base64);
  assert.equal(Buffer.from(payload.items[0].input_base64, 'base64').byteLength, 3112);
  const stages = JSON.parse(payload.items[0].stage_json);
  assert.equal(stages.raw_heavy_score, 0.25); assert.equal(stages.final_score, 0.3);
  assert.equal(validated.references[0].repo_id, golden.packet.snapshot.repo_id);
  assert.equal(JSON.stringify(validated).includes(golden.packet.input_base64), false);
  assert.equal(JSON.stringify(validated).includes('scored_at'), false);
  const changed = candidate(); changed.finalScore = 0.31;
  assert.notEqual(validate(golden.context, changed).references[0].record_digest, validated.references[0].record_digest,
    'stage metadata is part of immutable storage identity');
  assert.equal(JSON.parse(validated.serializeForPersistence({ ...policy, retentionDays: 90 })).retention_days, 90,
    '30 and90 are isolated fixture policies, not defaults');
});

test('packet/context ownership, complete shape, exact integers and encoding fail closed', () => {
  for (const mutate of [
    (context: any) => { context.user_id = '00000000-0000-4000-8000-000000000009'; },
    (context: any) => { context.feed_version = Number(context.feed_version); },
    (context: any) => { context.profile_version = '0'; },
    (context: any) => { delete context.profile_version; },
    (context: any) => { context.feedback_state_revision = '-1'; },
    (context: any) => { context.feedback_version = '9223372036854775808'; },
    (context: any) => { context.dimensions = 777; },
    (context: any) => { context.scored_at = '2026-02-30T00:00:00Z'; },
    (context: any) => { context.scored_at = '2026-10-24T00:00:00+05:30'; },
    (context: any) => { context.embedding_revision = 'bad'; },
    (context: any) => { context.unknown_field = true; },
  ]) { const context = structuredClone(golden.context); mutate(context); rejects(() => validate(context)); }
  for (const mutate of [
    (row: any) => { row.packet.snapshot.repo_id = row.packet.snapshot.repo_id.toUpperCase().replace('003', '00A'); },
    (row: any) => { row.packet.snapshot.feature_version = '-1'; },
    (row: any) => { row.packet.snapshot.embedding_version_index = 1; },
    (row: any) => { row.packet.input_base64 = row.packet.input_base64.slice(0, -1); },
    (row: any) => { row.packet.binding_sha256 = '0'.repeat(64); },
    (row: any) => { row.packet.extra = 'unknown'; },
    (row: any) => { row.finalScore = NaN; },
    (row: any) => { row.retrievalScores.semantic = Infinity; },
  ]) { const row = candidate(); mutate(row); rejects(() => validate(golden.context, row)); }
  const duplicate = candidate(); rejects(() => ValidatedScoringGeneration.validate(golden.context, [duplicate, duplicate], selector));
  rejects(() => ValidatedScoringGeneration.validate(golden.context, [], selector));
});

test('finite float32 and user-prefix checks are independent of a recomputed binding', () => {
  const row = candidate();
  const raw = Buffer.from(row.packet.input_base64, 'base64'); raw.writeFloatLE(Infinity, 2000);
  row.packet.input_base64 = raw.toString('base64');
  const canonicalContext = JSON.stringify(golden.context, Object.keys(golden.context).sort());
  const canonicalSnapshot = JSON.stringify(row.packet.snapshot, Object.keys(row.packet.snapshot).sort());
  row.packet.binding_sha256 = crypto.createHash('sha256')
    .update(Buffer.concat([Buffer.from('{"context":'+canonicalContext+',"snapshot":'+canonicalSnapshot+'}'),raw])).digest('hex');
  rejects(() => validate(golden.context, row));
  const changed = candidate(); changed.packet.input_base64 = Buffer.alloc(3112).toString('base64');
  rejects(() => validate(golden.context, changed));
});

test('capture remains off without explicit policy, cohort, capability and separate private pool', () => {
  assert.deepEqual(getScoringCaptureConfig({}), { enabled: false });
  assert.deepEqual(getScoringCaptureConfig({ SCORING_CAPTURE_ENABLED: 'false', SCORING_CAPTURE_RETENTION_DAYS: '30' }), { enabled: false });
  assert.throws(() => getScoringCaptureConfig({ SCORING_CAPTURE_ENABLED: 'true' }), /CONFIGURATION_INVALID/);
  const environment = { SCORING_CAPTURE_ENABLED: 'true', SCORING_CAPTURE_RETENTION_DAYS: '30',
    SCORING_CAPTURE_POLICY_ID: policy.policyId, SCORING_CAPTURE_POLICY_VERSION: policy.policyVersion,
    SCORING_CAPTURE_USER_IDS: selector.userId, SCORING_CAPTURE_CAPABILITY: 'a'.repeat(64),
    SCORING_CAPTURE_DATABASE_URL: 'postgresql://fixture_writer@127.0.0.1:55447/weave_scroll' };
  const configured = getScoringCaptureConfig(environment); assert.equal(configured.enabled, true);
  if (configured.enabled) assert.equal(configured.policy.retentionDays, 30);
  for (const changes of [{ SCORING_CAPTURE_RETENTION_DAYS: '' }, { SCORING_CAPTURE_RETENTION_DAYS: '366' },
    { SCORING_CAPTURE_USER_IDS: '' }, { SCORING_CAPTURE_CAPABILITY: '' },
    ...['g'.repeat(64),'A'.repeat(64),'a'.repeat(63),'a'.repeat(65),'a'.repeat(64)+'\n'].map(SCORING_CAPTURE_CAPABILITY=>({SCORING_CAPTURE_CAPABILITY})),
    { DATABASE_URL: environment.SCORING_CAPTURE_DATABASE_URL }]) {
    assert.throws(() => getScoringCaptureConfig({ ...environment, ...changes }), /CONFIGURATION_INVALID/);
  }
});
